package com.citysense.avatar;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.UUID;

/** A city service persona pinned on the Explore map. geom is generated by the database. */
@Entity
@Table(name = "avatars")
public class Avatar {

    @Id
    @GeneratedValue(strategy = GenerationType.UUID)
    private UUID id;

    @Column(nullable = false, unique = true)
    private String handle;
    @Column(nullable = false)
    private String name;
    @Column(nullable = false)
    private String title;
    @Column(nullable = false)
    private String category;
    @Column(nullable = false)
    private String persona;
    @Column(nullable = false)
    private String intro;
    private String pricing;
    @Column(name = "website_url")
    private String websiteUrl;
    @Column(name = "instagram_url")
    private String instagramUrl;
    @Column(name = "threads_url")
    private String threadsUrl;
    @Column(name = "x_url")
    private String xUrl;
    @Column(name = "pin_image", nullable = false)
    private String pinImage;
    @Column(name = "hero_image", nullable = false)
    private String heroImage;
    @Column(nullable = false)
    private BigDecimal rating = BigDecimal.ZERO;
    @Column(name = "review_count", nullable = false)
    private int reviewCount;
    @Column(nullable = false)
    private double latitude;
    @Column(nullable = false)
    private double longitude;
    @Column(nullable = false)
    private boolean active = true;
    @Column(name = "created_at", nullable = false, updatable = false)
    private Instant createdAt = Instant.now();

    protected Avatar() {}

    public Avatar(String handle) {
        this.handle = handle;
    }

    public UUID getId() { return id; }
    public String getHandle() { return handle; }
    public String getName() { return name; }
    public String getTitle() { return title; }
    public String getCategory() { return category; }
    public String getPersona() { return persona; }
    public String getIntro() { return intro; }
    public String getPricing() { return pricing; }
    public String getWebsiteUrl() { return websiteUrl; }
    public String getInstagramUrl() { return instagramUrl; }
    public String getThreadsUrl() { return threadsUrl; }
    public String getXUrl() { return xUrl; }
    public String getPinImage() { return pinImage; }
    public String getHeroImage() { return heroImage; }
    public BigDecimal getRating() { return rating; }
    public int getReviewCount() { return reviewCount; }
    public double getLatitude() { return latitude; }
    public double getLongitude() { return longitude; }
    public boolean isActive() { return active; }

    /** Copies seed fields; used by AvatarSeeder only. */
    void apply(AvatarSeeder.SeedAvatar s) {
        this.name = s.name();
        this.title = s.title();
        this.category = s.category();
        this.persona = s.persona();
        this.intro = s.intro();
        this.pricing = s.pricing();
        this.websiteUrl = s.websiteUrl();
        this.instagramUrl = s.instagramUrl();
        this.threadsUrl = s.threadsUrl();
        this.xUrl = s.xUrl();
        this.pinImage = s.pinImage();
        this.heroImage = s.heroImage();
        this.rating = s.rating() == null ? BigDecimal.ZERO : s.rating();
        this.reviewCount = s.reviewCount();
        this.latitude = s.latitude();
        this.longitude = s.longitude();
        this.active = true;
    }
}
